arguments.argument:
if (owner.cancelAbility[1] == ACANCEL_ALARM) owner.abilityActive[1] = false;
switch(owner.ability[1])
{
    case ABILITY_INVULN:
        owner.currentWeapon.readyToShoot = true;
        owner.currentWeapon.readyToStab = true;
        owner.currentWeapon.readyToFlare = true;
        owner.currentWeapon.readyToBlast = true;
        playsound(x,y,UberEndSnd);
        owner.maxDuration = 121;
    break;
    case ABILITY_CRIT:
    case ABILITY_MINICRIT:
        owner.currentWeapon.crit = 1;
    break;
}
if (owner.rechargeAbility[1] == ACHARGE_ALARM)
{
    owner.meter[1] = owner.maxMeter[1];
    if (owner.weaponType[1] == WTYPE_THROWABLE and owner.currentWeapon.activeWeapon == 1) owner.currentWeapon.ammoCount = owner.currentWeapon.maxAmmo;
} 
if (owner.depleteAbility[1] == ADEPLETE_ALARM) owner.meter[1] = 0;
if (owner.weaponType[1] != WTYPE_CONSUMABLE and owner.weaponType[1] != WTYPE_BANNER) playsound(x,y,rechargeSnd);
